from collections import deque, Counter

def transform(grid):
    rows = len(grid)
    if rows == 0: return grid
    cols = len(grid[0])
    if cols == 0: return grid

    # Find background (most frequent)
    freq = Counter()
    for row in grid:
        freq[row[0]] += 1 * len(list(row))
    background = max(freq.keys(), key=lambda x: freq[x])

    # Structure is the non-background value that forms connected components
    # Seeds are the rare values
    non_bg = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                non_bg[grid[r][c]] = non_bg.get(grid[r][c], 0) + 1

    # Sort by frequency: highest non-bg is likely structure
    sorted_non_bg = sorted(non_bg.keys(), key=lambda x: non_bg[x], reverse=True)

    if len(sorted_non_bg) == 0:
        return grid

    structure = sorted_non_bg[0]
    seeds = sorted_non_bg[1:] if len(sorted_non_bg) > 1 else []
    seed_values = list(seeds) if seeds else [structure]

    # Build adjacency map for structure cells
    result = [row[:] for row in grid]
    modified = set()
    queue = deque()

    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    # Find all seed locations and their neighbors
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] in seed_values:
                seed_val = grid[r][c]
                for nr, nc in get_neighbors(r, c):
                    if grid[nr][nc] == structure:
                        # Alternate value based on seed
                        if seed_val == seed_values[0]:
                            alt = seed_values[1] if len(seed_values) > 1 else seed_values[0]
                        else:
                            alt = seed_values[0] if len(seed_values) > 1 else seed_values[0]

                        result[nr][nc] = alt
                        modified.add((nr, nc))
                        queue.append(((nr, nc), alt))

    # Propagate through connected structure
    while queue:
        (r, c), val = queue.popleft()
        for nr, nc in get_neighbors(r, c):
            if 0 <= nr < rows and 0 <= nc < cols:
                if result[nr][nc] == structure and (nr, nc) not in modified:
                    if val == seed_values[0]:
                        alt = seed_values[1] if len(seed_values) > 1 else seed_values[0]
                    else:
                        alt = seed_values[0] if len(seed_values) > 1 else seed_values[0]

                    result[nr][nc] = alt
                    modified.add((nr, nc))
                    queue.append(((nr, nc), alt))

    return result
